import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import YAML from '/ws/AiWorks/dominds/node_modules/yaml';
import { readBuiltinDefaultsYamlRaw, type ProviderConfig, type ChatMessage } from '/ws/AiWorks/dominds/main/llm/client';
import { OpenAiGen } from '/ws/AiWorks/dominds/main/llm/gen/openai';
import { Team } from '/ws/AiWorks/dominds/main/team';
import type { FuncTool } from '/ws/AiWorks/dominds/main/tool';
import { liveCapture } from '/ws/AiWorks/dominds/tests/helpers/live-provider';

const directory = '/tmp/dominds-ltsp-openai-67id4168';
const mode = process.argv[2] || 'stream';
let secret = '';
let complete = false;
const wire: Array<Record<string, unknown>> = [];
const pendingAudits: Array<Promise<void>> = [];
const attempts: Array<Record<string, unknown>> = [];
const redact = (value: string) => secret ? value.split(secret).join('[REDACTED]') : value;
process.once('beforeExit', () => { if (!complete) { console.error('Probe completion boundary was not reached'); process.exitCode=1; } });

async function main() {
  let inputText = '';
  for await (const chunk of process.stdin) inputText += chunk.toString();
  const input = JSON.parse(inputText);
  secret = input.key;
  assert.equal(typeof secret, 'string');
  assert.ok(secret.length > 10);
  process.env.DOMINDS_LTSP_OPENAI_TEST_KEY = secret;
  const nativeFetch = globalThis.fetch.bind(globalThis);
  globalThis.fetch = async (input, init) => {
    const request = new Request(input, init);
    const url = new URL(request.url);
    assert.equal(url.origin, 'http://172.16.100.254:8080');
    const body = request.method === 'POST' ? JSON.parse(await request.clone().text()) : undefined;
    const entry: Record<string, unknown> = {method:request.method, path:url.pathname, body, startedAt:new Date().toISOString()};
    wire.push(entry);
    const response = await nativeFetch(input, init);
    entry.status = response.status;
    entry.headers = Object.fromEntries(['content-type','x-request-id','x-bifrost-request-id','x-bf-request-id','openai-processing-ms'].map(key=>[key,response.headers.get(key)]));
    const copy=response.clone();
    pendingAudits.push(copy.text().then(raw=>{
      entry.rawResponse = redact(raw);
      const packets: unknown[] = [];
      if ((response.headers.get('content-type') || '').includes('text/event-stream')) {
        for (const line of raw.split('\n')) {
          if (!line.startsWith('data:')) continue;
          const data=line.slice(5).trim();
          if (data && data!=='[DONE]') packets.push(JSON.parse(data));
        }
      } else if (raw) packets.push(JSON.parse(raw));
      entry.packets=packets;
    }));
    return response;
  };
  const defaults=YAML.parse(await readBuiltinDefaultsYamlRaw());
  const canonical=mode.startsWith('batch:')?mode.slice(6):'gpt-6.1-terra';
  const metadata=defaults.providers.openai.models[canonical];
  assert.ok(metadata, 'The selected canonical model must be configured in built-in defaults');
  const model='openai/'+canonical;
  const provider: ProviderConfig={...defaults.providers.openai, baseUrl:'http://172.16.100.254:8080/openai', apiKeyEnvVar:'DOMINDS_LTSP_OPENAI_TEST_KEY', models:{[model]:metadata}};
  const agent=new Team.Member({id:'ltsp-gateway-probe',name:'LTSP gateway probe',provider:'ltsp-openai',model,model_params:{openai:{reasoning_effort:'low',verbosity:'low',parallel_tool_calls:false}}});
  const generator=new OpenAiGen();
  const request={dialogSelfId:'ltsp-gateway-probe',dialogRootId:'ltsp-gateway-probe',providerKey:'ltsp-openai',modelKey:model,toolUseRequirement:'none' as const};
  const context: ChatMessage[]=[{type:'prompting_msg',role:'user',genseq:1,msgId:'connectivity-'+randomUUID(),grammar:'markdown',content:'Reply in one short sentence for a connectivity check. No writing-quality evaluation is requested.'}];
  if (mode==='stream') {
    const capture=liveCapture(1);
    const result=await generator.genToReceiver(provider,agent,'',[],request,context,capture.receiver,1,AbortSignal.timeout(30000));
    capture.assertComplete();
    assert.ok(capture.capture.sayingChunks.join('').length>0);
    assert.equal(capture.capture.calls.length,0);
    assert.equal(result.usage?.kind,'available');
    attempts.push({mode,model,status:'passed',context,result,capture:capture.capture,metadata});
  } else if(mode==='tools') {
    const nonce=randomUUID();
    const given={nonce};
    const tools: FuncTool[]=[{type:'func',name:'capture_nonce',description:'Capture an opaque supplied nonce. No external command or action is executed.',parameters:{type:'object',properties:{nonce:{type:'string'}},required:['nonce'],additionalProperties:false},call:async()=>{throw new Error('This transport probe must not execute a tool');}}];
    context[0]={...context[0],content:'Call capture_nonce once with this supplied JSON: '+JSON.stringify(given)+'. After receiving its result, return a JSON object containing the supplied receipt.'};
    const capture=liveCapture(1);
    const first=await generator.genToReceiver(provider,agent,'',tools,{...request,toolUseRequirement:'required'},context,capture.receiver,1,AbortSignal.timeout(30000));
    capture.assertComplete();assert.equal(capture.capture.calls.length,1);
    const call=capture.capture.calls[0];assert.equal(call.name,'capture_nonce');assert.deepEqual(JSON.parse(call.args),given);
    const receipt=randomUUID();
    const resultMessage: ChatMessage={type:'func_result_msg',role:'tool',genseq:1,id:call.id,name:call.name,content:JSON.stringify({receipt})};
    const nextContext=[...context,...capture.capture.messages,resultMessage];
    agent.model_params={openai:{...agent.model_params?.openai,text_format:'json_schema',text_format_json_schema_name:'gateway_receipt',text_format_json_schema:JSON.stringify({type:'object',properties:{receipt:{type:'string'}},required:['receipt'],additionalProperties:false}),text_format_json_schema_strict:true}};
    const second=await generator.genMoreMessages(provider,agent,'',tools,request,nextContext,2,AbortSignal.timeout(30000));
    assert.equal(second.messages.filter(m=>m.type==='func_call_msg').length,0);
    const text=second.messages.filter(m=>m.type==='saying_msg').map(m=>m.content).join('');
    // Exact opaque supplied JSON data fidelity; no natural-language meaning is matched.
    assert.deepEqual(JSON.parse(text),{receipt});
    attempts.push({mode,model,status:'passed',given,receipt,first,capture:capture.capture,nextContext,second,toolExecuted:false});
  } else if(mode.startsWith('batch:')) {
    const result=await generator.genMoreMessages(provider,agent,'',[],request,context,1,AbortSignal.timeout(30000));
    assert.equal(result.usage?.kind,'available');assert.equal(result.messages.filter(m=>m.type==='func_call_msg').length,0);
    assert.ok(result.messages.some(m=>m.type==='saying_msg' && m.content.length>0));
    attempts.push({mode,model,status:'passed',context,result,metadata});
  } else throw new Error('Unknown phase');
  await Promise.all(pendingAudits);
  for(const row of wire) {
    assert.equal(row.status,200);
    const body=row.body as Record<string,unknown>;assert.equal(body.temperature,undefined);assert.equal(body.top_p,undefined);
    assert.deepEqual(body.reasoning,{effort:'low'});
    if(body.stream===true) {
      const packets=row.packets as Array<Record<string,unknown>>;
      assert.equal(packets.filter(p=>p.type==='response.completed').length,1);
    }
  }
}
void main().catch(error=>{
 attempts.push({mode,status:'failed',error:redact(error instanceof Error?error.stack || error.message:String(error))});
 process.exitCode=1;
}).finally(async()=>{
 await Promise.allSettled(pendingAudits);
 await fs.writeFile(path.join(directory,mode.replace(/[^a-zA-Z0-9.-]/g,'_')+'.json'),redact(JSON.stringify({mode,observedAt:new Date().toISOString(),semanticAcceptance:'not-assessed',credentialStored:false,attempts,wire},null,2))+'\n');
 delete process.env.DOMINDS_LTSP_OPENAI_TEST_KEY;
 complete=true;
 console.log(JSON.stringify({phase:mode,status:process.exitCode?'failed':'passed',requests:wire.length,evidenceDirectory:directory}));
});

