import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import YAML from '/ws/AiWorks/dominds/node_modules/yaml';
import { LlmConfig } from '/ws/AiWorks/dominds/main/llm/client';
async function main() {
 const example=YAML.parse(await fs.readFile('/ws/AiWorks/dominds/docs/examples/ltsp-openai.llm.yaml','utf8'));
 const prior=YAML.parse(await fs.readFile('.minds/llm.yaml','utf8'));
 await fs.writeFile('.minds/llm.yaml',YAML.stringify({providers:{...prior.providers,...example.providers}}));
 const actual=await LlmConfig.load();const provider=actual.getProvider('ltsp-openai');assert.ok(provider);
 assert.equal(provider.apiType,'openai');assert.equal(provider.baseUrl,'http://172.16.100.254:8080/openai');assert.equal(provider.apiKeyEnvVar,'LTSP_OPENAI_API_KEY');
 const builtin=actual.getProvider('openai');assert.ok(builtin);assert.equal(builtin.baseUrl,'https://api.openai.com/v1');
 for(const [id,metadata] of Object.entries(provider.models)){assert.ok(id.startsWith('openai/'));assert.deepEqual(metadata,builtin.models[id.slice(7)]);}
 assert.equal(Object.keys(provider.models).length,5);
 for(const [id,data] of Object.entries(prior.providers))assert.deepEqual(actual.getProvider(id),data);
 const result={provider,officialProviderUnchanged:builtin.baseUrl,existingWorkspaceProvidersPreserved:Object.keys(prior.providers),networkRequests:0};
 await fs.writeFile('/tmp/dominds-ltsp-openai-67id4168/example-load.json',JSON.stringify(result,null,2)+'\n');
 console.log('Example configuration loaded through native LlmConfig; five wire-model definitions preserve canonical metadata; no network request.');
}
void main().catch(error=>{console.error(error);process.exitCode=1});
